    if (rot > 90) rot -= 180;
    else if (rot < -90) rot += 180;
    const finalRot = l.metricRotation !== undefined ? l.metricRotation : rot;
    const theta = finalRot * (Math.PI / 180);
    return { dx: 25 * Math.sin(theta), dy: -25 * Math.cos(theta) };
};

