const cadPolygons = React.useMemo(() => {
  if (cadLines.length < 3) return [];

  const faces = [];
  let faceIdCounter = 0;

  const surveyGroups = [ { id: null }, ...multiSurveyData ];

  surveyGroups.forEach(survey => {
      const surveyLines = cadLines.filter(l => (survey.id === null ? !l.surveyId : l.surveyId === survey.id));
      if (surveyLines.length < 1) return;

      const surveyNodes = new Set();
      surveyLines.forEach(l => {
          surveyNodes.add(`${l.p1.x.toFixed(3)},${l.p1.y.toFixed(3)}`);
          surveyNodes.add(`${l.p2.x.toFixed(3)},${l.p2.y.toFixed(3)}`);
      });

      const injectedLines = cadLines.filter(l => {
          const lSurveyId = l.surveyId || null;
          return lSurveyId !== survey.id && 
                 surveyNodes.has(`${l.p1.x.toFixed(3)},${l.p1.y.toFixed(3)}`) && 
                 surveyNodes.has(`${l.p2.x.toFixed(3)},${l.p2.y.toFixed(3)}`);
      });

      const linesForGraph = [...surveyLines, ...injectedLines];
      if (linesForGraph.length < 3) return;

      const nodesMap = new Map();
      const getOrAddNode = (x, y) => {
         const key = `${x.toFixed(3)},${y.toFixed(3)}`;
         if (!nodesMap.has(key)) nodesMap.set(key, { x, y, edges: [] });
         return nodesMap.get(key);
      };

      linesForGraph.forEach(l => {
         const n1 = getOrAddNode(l.p1.x, l.p1.y);
         const n2 = getOrAddNode(l.p2.x, l.p2.y);
         n1.edges.push({ tgt: n2, line: l });
         n2.edges.push({ tgt: n1, line: l });
      });

      const nodes = Array.from(nodesMap.values());
      const halfEdges = new Map(); 

      nodes.forEach(n => {
         n.edges.forEach(edgeObj => {
             const tgt = edgeObj.tgt;
             const l = edgeObj.line;
             const dx = tgt.x - n.x;
             const dy = tgt.y - n.y;
             const angle = Math.atan2(dy, dx);
             const k = `${n.x.toFixed(3)},${n.y.toFixed(3)}->${tgt.x.toFixed(3)},${tgt.y.toFixed(3)}`;
             halfEdges.set(k, { from: n, to: tgt, angle, key: k, line: l });
         });
      });

      nodes.forEach(n => {
         const outEdges = n.edges.map(edgeObj => {
             const tgt = edgeObj.tgt;
             const k = `${n.x.toFixed(3)},${n.y.toFixed(3)}->${tgt.x.toFixed(3)},${tgt.y.toFixed(3)}`;
             return halfEdges.get(k);
         }).sort((a, b) => a.angle - b.angle);

         for (let i = 0; i < outEdges.length; i++) {
             const current = outEdges[i];
             const prev = outEdges[(i - 1 + outEdges.length) % outEdges.length];
             const revK = `${prev.to.x.toFixed(3)},${prev.to.y.toFixed(3)}->${prev.from.x.toFixed(3)},${prev.from.y.toFixed(3)}`;
             const incomingToN = halfEdges.get(revK);
             if (incomingToN) {
                 incomingToN.next = current;
             }
         }
      });

      const visited = new Set();

      for (let he of halfEdges.values()) {
          if (visited.has(he.key)) continue;

          const faceEdges = [];
          let curr = he;
          let isClosed = false;
          let sanity = 0;
          do {
              visited.add(curr.key);
              faceEdges.push(curr);
              curr = curr.next;
              sanity++;
              if (!curr) break;
              if (curr.key === he.key) { isClosed = true; break; }
          } while (sanity < 1000);

          if (isClosed && faceEdges.length >= 3) {
              let area = 0;
              const pts = faceEdges.map(e => e.from);
              for (let i = 0; i < pts.length; i++) {
                  const j = (i + 1) % pts.length;
                  area += (pts[i].x * pts[j].y - pts[j].x * pts[i].y);
              }
              area = area / 2;

              // CCW traversal -> negative area in SVG coordinates
              if (area < -1e-4) {
                  faces.push({ id: `poly_${faceIdCounter++}`, pts, area: Math.abs(area), surveyId: survey.id });
              }
          }
      }
  });

  return faces;
}, [cadLines, multiSurveyData]);

