if (bgDragGesture && bgDragGesture.isDragging) {
   const pt = cadSvgRef.current.createSVGPoint();
   pt.x = e.clientX; pt.y = e.clientY;
   const svgP = pt.matrixTransform(cadSvgRef.current.getScreenCTM().inverse());
   const dx = svgP.x - bgDragGesture.startX;
   const dy = svgP.y - bgDragGesture.startY;

   const activeLayer = bgDragGesture.origLayers.find(l => l.id === bgDragGesture.id);
   const isLinkedDrag = activeLayer && activeLayer.isLinked;

   setBackgroundLayers(bgDragGesture.origLayers.map(l => {
       const isTarget = l.id === bgDragGesture.id;
       const isLinkedTarget = isLinkedDrag && l.isLinked && !l.isFrozen;
       if (!isTarget && !isLinkedTarget) return l;

       if (bgDragGesture.action === 'resize') {
           let newX = l.x;
           let newY = l.y;
           let newW = l.w;
           let newH = l.h;
           const minSize = 50;
           const handle = bgDragGesture.handle;

           if (handle.includes('l')) {
               let possibleW = l.w - dx;
               if (possibleW >= minSize) {
                   newW = possibleW;
                   newX = l.x + dx;
               } else {
                   newW = minSize;
                   newX = l.x + (l.w - minSize);
               }
           }
           if (handle.includes('r')) {
               newW = Math.max(minSize, l.w + dx);
           }
           if (handle.includes('t')) {
               let possibleH = l.h - dy;
               if (possibleH >= minSize) {
                   newH = possibleH;
                   newY = l.y + dy;
               } else {
                   newH = minSize;
                   newY = l.y + (l.h - minSize);
               }
           }
           if (handle.includes('b')) {
               newH = Math.max(minSize, l.h + dy);
           }

           return { ...l, x: newX, y: newY, w: newW, h: newH };
       } else {
           return { ...l, x: l.x + dx, y: l.y + dy };
       }
   }));
   return;
}

