              startX: svgP.x, 
              startY: svgP.y, 
              isDragging: true,
              action: 'pan',
              origLayers: backgroundLayers
          });
      }}
      onWheel={(e) => {
          if (layer.isFrozen) return;
          e.stopPropagation();
          e.preventDefault();
          const scaleAdjust = e.deltaY > 0 ? 0.95 : 1.05;

          const ctm = e.currentTarget.ownerSVGElement.getScreenCTM();
          const pt = e.currentTarget.ownerSVGElement.createSVGPoint();
          pt.x = e.clientX; pt.y = e.clientY;
          const svgP = pt.matrixTransform(ctm.inverse());
          const ox = svgP.x;
          const oy = svgP.y;

          setBackgroundLayers(prev => prev.map(l => {
              const isTarget = l.id === layer.id;
              const isLinked = layer.isLinked && l.isLinked && !l.isFrozen;

              if (isTarget || isLinked) {
                  const minSize = 50;
                  let newW = l.w * scaleAdjust;
                  let newH = l.h * scaleAdjust;
                  if (newW < minSize || newH < minSize) {
                      const limitRatio = Math.max(minSize / l.w, minSize / l.h);
                      newW = l.w * limitRatio;
                      newH = l.h * limitRatio;
                      return {
                          ...l,
                          w: newW,
                          h: newH,
                          x: ox + (l.x - ox) * limitRatio,
                          y: oy + (l.y - oy) * limitRatio
                      };
                  }
                  return {
                      ...l,
                      w: newW,
                      h: newH,
                      x: ox + (l.x - ox) * scaleAdjust,
                      y: oy + (l.y - oy) * scaleAdjust
                  };
              }
              return l;
          }));
      }}
   />
   {!layer.isFrozen && (
