               { id: 'bl', cx: layer.x, cy: layer.y + layer.h, cursor: 'nesw-resize' },
               { id: 'br', cx: layer.x + layer.w, cy: layer.y + layer.h, cursor: 'nwse-resize' },
               { id: 't', cx: layer.x + layer.w/2, cy: layer.y, cursor: 'ns-resize' },
               { id: 'b', cx: layer.x + layer.w/2, cy: layer.y + layer.h, cursor: 'ns-resize' },
               { id: 'l', cx: layer.x, cy: layer.y + layer.h/2, cursor: 'ew-resize' },
               { id: 'r', cx: layer.x + layer.w, cy: layer.y + layer.h/2, cursor: 'ew-resize' }
           ].map(h => (
               <g key={h.id} onPointerDown={(e) => {
                   if (cadTool !== 'IDLE') return;
                   e.stopPropagation();
                   const ctm = e.currentTarget.ownerSVGElement.getScreenCTM();
                   const pt = e.currentTarget.ownerSVGElement.createSVGPoint();
                   pt.x = e.clientX; pt.y = e.clientY;
                   const svgP = pt.matrixTransform(ctm.inverse());
                   setBgDragGesture({ 
                       id: layer.id, 
                       startX: svgP.x, 
                       startY: svgP.y, 
                       isDragging: true,
                       action: 'resize',
                       handle: h.id,
                       origLayers: backgroundLayers
                   });
               }} cursor={h.cursor}>
                   <circle cx={h.cx} cy={h.cy} r={cadViewport.width * 0.02} fill="transparent" />
                   <circle cx={h.cx} cy={h.cy} r={cadViewport.width * 0.005} fill="white" stroke="#38bdf8" strokeWidth={cadViewport.width * 0.001} pointerEvents="none" />
               </g>
           ))}
       </g>
   )}
   </g>
))}

